func report(level string, msgs ...string) {
    fmt.Println(level, len(msgs))
    for _, msg := range msgs {
        fmt.Println("-", msg)
    }
}

func main() {
    report("warn", "disk low", "retry soon")
    report("info")
}

func longest(words ...string) string {
    best := ""
    for _, word := range words {
        if len(word) > len(best) {
            best = word
        }
    }
    return best
}

